### Python

```python
# -*- coding: utf-8 -*-
import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        print(-1)
        return

    try:
        N = int(lines[0])
    except:
        print(-1)
        return

    # 需要 N 行文档 + 1 行 k 值
    if len(lines) != N + 2:
        print(-1)
        return

    positive_count = 0
    negative_count = 0
    word_counts = {}  # key: word, value: [A, B]

    for i in range(1, N + 1):
        line = lines[i]
        if "\t" in line:
            label, text = line.split("\t", 1)
        else:
            # 兼容无制表符的情况：第一个单词为标签，其余为文本
            parts = line.split()
            if len(parts) < 2:
                print(-1)
                return
            label = parts[0]
            text = " ".join(parts[1:])

        if label == "positive":
            positive_count += 1
            is_positive = True
        elif label == "negative":
            negative_count += 1
            is_positive = False
        else:
            print(-1)
            return

        # 词袋处理：集合去重
        words = set(text.split())
        for word in words:
            if word not in word_counts:
                word_counts[word] = [0, 0]
            if is_positive:
                word_counts[word][0] += 1
            else:
                word_counts[word][1] += 1

    total = positive_count + negative_count
    features = []

    for word, (A, B) in word_counts.items():
        C = positive_count - A
        D = negative_count - B

        row1 = A + B  # 含有该单词的文档总数
        row2 = C + D  # 不含该单词的文档总数
        col1 = positive_count
        col2 = negative_count

        S = 0.0
        # 计算四个单元格对 S 的贡献
        if row1 > 0 and col1 > 0:
            E = row1 * col1 / total
            if E > 0:
                S += (A - E) ** 2 / E
        if row1 > 0 and col2 > 0:
            E = row1 * col2 / total
            if E > 0:
                S += (B - E) ** 2 / E
        if row2 > 0 and col1 > 0:
            E = row2 * col1 / total
            if E > 0:
                S += (C - E) ** 2 / E
        if row2 > 0 and col2 > 0:
            E = row2 * col2 / total
            if E > 0:
                S += (D - E) ** 2 / E

        features.append((word, S))

    # 按 S 降序，相同时按单词字典序升序
    features.sort(key=lambda x: (-x[1], x[0]))

    try:
        k = int(lines[-1])
    except:
        print(-1)
        return

    out_count = min(k, len(features))
    for i in range(out_count):
        print(features[i][0])

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

class Feature {
    String word;
    double score;
    Feature(String w, double s) { word = w; score = s; }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) {
            System.out.println(-1);
            return;
        }

        int N;
        try {
            N = Integer.parseInt(line.trim());
        } catch (Exception e) {
            System.out.println(-1);
            return;
        }

        List<String> docs = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            String doc = br.readLine();
            if (doc == null) {
                System.out.println(-1);
                return;
            }
            docs.add(doc);
        }

        String kLine = br.readLine();
        if (kLine == null) {
            System.out.println(-1);
            return;
        }
        int k;
        try {
            k = Integer.parseInt(kLine.trim());
        } catch (Exception e) {
            System.out.println(-1);
            return;
        }

        int positiveCount = 0, negativeCount = 0;
        Map<String, int[]> wordCount = new HashMap<>(); // [A, B]

        for (String doc : docs) {
            String label, text;
            if (doc.contains("\t")) {
                String[] parts = doc.split("\t", 2);
                if (parts.length < 2) {
                    System.out.println(-1);
                    return;
                }
                label = parts[0];
                text = parts[1];
            } else {
                String[] parts = doc.split(" ");
                if (parts.length < 2) {
                    System.out.println(-1);
                    return;
                }
                label = parts[0];
                text = String.join(" ", Arrays.copyOfRange(parts, 1, parts.length));
            }

            boolean isPositive;
            if (label.equals("positive")) {
                positiveCount++;
                isPositive = true;
            } else if (label.equals("negative")) {
                negativeCount++;
                isPositive = false;
            } else {
                System.out.println(-1);
                return;
            }

            String[] words = text.split(" ");
            Set<String> wordSet = new HashSet<>(Arrays.asList(words));
            for (String word : wordSet) {
                int[] counts = wordCount.getOrDefault(word, new int[2]);
                if (isPositive) counts[0]++;
                else counts[1]++;
                wordCount.put(word, counts);
            }
        }

        int total = positiveCount + negativeCount;
        List<Feature> features = new ArrayList<>();

        for (Map.Entry<String, int[]> entry : wordCount.entrySet()) {
            String word = entry.getKey();
            int A = entry.getValue()[0];
            int B = entry.getValue()[1];
            int C = positiveCount - A;
            int D = negativeCount - B;

            int row1 = A + B;
            int row2 = C + D;
            int col1 = positiveCount;
            int col2 = negativeCount;

            double S = 0.0;
            if (row1 > 0 && col1 > 0) {
                double E = (double) row1 * col1 / total;
                if (E > 0) S += (A - E) * (A - E) / E;
            }
            if (row1 > 0 && col2 > 0) {
                double E = (double) row1 * col2 / total;
                if (E > 0) S += (B - E) * (B - E) / E;
            }
            if (row2 > 0 && col1 > 0) {
                double E = (double) row2 * col1 / total;
                if (E > 0) S += (C - E) * (C - E) / E;
            }
            if (row2 > 0 && col2 > 0) {
                double E = (double) row2 * col2 / total;
                if (E > 0) S += (D - E) * (D - E) / E;
            }

            features.add(new Feature(word, S));
        }

        features.sort((a, b) -> {
            if (Math.abs(a.score - b.score) > 1e-9)
                return Double.compare(b.score, a.score);
            return a.word.compareTo(b.word);
        });

        for (int i = 0; i < k && i < features.size(); i++)
            System.out.println(features.get(i).word);
    }
}
